"use client";

import React, { useEffect, useState } from "react";
import { Loader2, Plus, Edit2, Trash2 } from "lucide-react";
import { API_BASE } from "@/lib/api";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

function getAuthHeaders() {
  try {
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    return {
      "x-user-id": user.id || "",
    };
  } catch {
    return { "x-user-id": "" };
  }
}

export default function ReferralOffersPage() {
  const [offers, setOffers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [formData, setFormData] = useState({
    required_invites: 5,
    reward_days: 1,
    reward_type: "PRO_ACCESS",
    is_active: false
  });

  const fetchOffers = async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${API_BASE}/content/admin/referral-offers`, { headers: getAuthHeaders() });
      const data = await res.json();
      if (data.success) {
        setOffers(data.data);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOffers();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetchWithAuth(`${API_BASE}/content/admin/referral-offers`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });
      if (res.ok) {
        fetchOffers();
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Delete referral offer?")) return;
    try {
      await fetchWithAuth(`${API_BASE}/content/admin/referral-offers/${id}`, {
        method: "DELETE",
        headers: getAuthHeaders()
      });
      fetchOffers();
    } catch (e) {
      console.error(e);
    }
  };

  const toggleStatus = async (c: any) => {
    const newStatus = !c.is_active;
    try {
      await fetchWithAuth(`${API_BASE}/content/admin/referral-offers/${c.id}`, {
        method: "PUT",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ is_active: newStatus })
      });
      fetchOffers();
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="p-8 font-sans antialiased bg-app min-h-screen text-main">
      <h1 className="text-2xl font-bold mb-6">Referral Offer Manager</h1>

      <div className="bg-card p-6 rounded-xl border border-subtle mb-8">
        <h2 className="text-lg font-semibold mb-4">Create Referral Offer</h2>
        <form onSubmit={handleSubmit} className="flex flex-col gap-4 max-w-lg">
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" type="number" placeholder="Required Invites" value={formData.required_invites} onChange={e => setFormData({ ...formData, required_invites: parseInt(e.target.value) })} required />
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" type="number" placeholder="Reward Days" value={formData.reward_days} onChange={e => setFormData({ ...formData, reward_days: parseInt(e.target.value) })} required />
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" placeholder="Reward Type (e.g. PRO_ACCESS)" value={formData.reward_type} onChange={e => setFormData({ ...formData, reward_type: e.target.value })} required />
          <label className="flex items-center gap-2 text-sm">
            <input type="checkbox" checked={formData.is_active} onChange={e => setFormData({ ...formData, is_active: e.target.checked })} />
            Set as Active
          </label>
          <button type="submit" className="bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-2 rounded-lg text-sm">Add Offer</button>
        </form>
      </div>

      <div className="bg-card rounded-xl border border-subtle overflow-hidden">
        {loading ? <div className="p-8 flex justify-center"><Loader2 className="animate-spin text-indigo-500" /></div> : (
          <table className="w-full text-sm text-left">
            <thead className="bg-input border-b border-subtle text-muted text-xs uppercase font-bold">
              <tr>
                <th className="px-4 py-3">Required Invites</th>
                <th className="px-4 py-3">Reward Days</th>
                <th className="px-4 py-3">Type</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody>
              {offers.map(c => (
                <tr key={c.id} className="border-b border-subtle hover:bg-input/50">
                  <td className="px-4 py-3">{c.required_invites}</td>
                  <td className="px-4 py-3">{c.reward_days}</td>
                  <td className="px-4 py-3">{c.reward_type}</td>
                  <td className="px-4 py-3">
                    <button onClick={() => toggleStatus(c)} className={`px-2 py-1 rounded text-xs font-bold ${c.is_active ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
                      {c.is_active ? "Active" : "Inactive"}
                    </button>
                  </td>
                  <td className="px-4 py-3 flex gap-2">
                    <button onClick={() => handleDelete(c.id)} className="text-red-400 hover:text-red-300"><Trash2 size={16}/></button>
                  </td>
                </tr>
              ))}
              {offers.length === 0 && (
                <tr><td colSpan={5} className="px-4 py-6 text-center text-muted">No offers found.</td></tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
